import threading, sys, traceback, importlib
NAMES = ["queue","cPickle","configparser","http_client","html_parser","socketserver",
         "_thread","builtins","reprlib","copyreg","tkinter","email_mime_text",
         "urllib.parse","urllib.error","urllib.request","urllib.response","urllib.robotparser",
         "urllib_parse","urllib_error","xmlrpc_client","collections_abc","dbm_gnu","BaseHTTPServer"]
errors = []
barrier = threading.Barrier(16)
def work(tid):
    try:
        barrier.wait()
        for _ in range(6):
            for n in NAMES:
                importlib.import_module("six.moves." + n)
            import six
            six.moves.range; six.moves.reduce; six.moves.zip
    except BaseException as e:
        errors.append((tid, traceback.format_exc()))
ts = [threading.Thread(target=work, args=(i,)) for i in range(16)]
for t in ts: t.start()
for t in ts:
    t.join(timeout=60)
    if t.is_alive():
        errors.append((-1, "DEADLOCK: thread still alive after 60s"))
print("threads done, error count =", len(errors))
for tid, tb in errors[:5]:
    print("--- thread", tid, "---"); print(tb)
EOF
timeout 120 python -W error /tmp/edges/thr.py; echo "exit=$?"
